    async function start() {
      const { CreatorArtwork } = await import('@/game/render/creator-artwork');
      if (cancelled) return;
      renderer = new CreatorArtwork(pack, 550);
      await renderer.init();
      if (cancelled) { renderer.destroy(); return; }
