          ctx.setTransform(1, 0, 0, 1, 0, 0); ctx.clearRect(0, 0, canvas.width, canvas.height);
          ctx.setTransform(2, 0, 0, 2, 550, 550);
          if (!placements.has(index)) {
            renderer.draw(ctx, layer, parts, age);
